import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.D90SBk1D.js";var i=JSON.parse(`{"title":"What is not included","description":"","frontmatter":{},"headers":[],"relativePath":"limits/not-included.md","filePath":"limits/not-included.md","lastUpdated":1786917909000}`),a={name:`limits/not-included.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-not-included" tabindex="-1">What is not included <a class="header-anchor" href="#what-is-not-included" aria-label="Permalink to “What is not included”">​</a></h1><p>This page is the contract for <code>0.2.x</code>. When a feature ships, the bullet leaves this list.</p><h2 id="writes" tabindex="-1">Writes <a class="header-anchor" href="#writes" aria-label="Permalink to “Writes”">​</a></h2><ul><li>Nested <code>create</code> / <code>connect</code> / <code>set</code> payloads</li><li>Many-to-many editors</li><li><code>hasMany</code> inline tables on the parent form</li><li>File / <code>Bytes</code> uploads</li><li>Rich text or custom widgets</li></ul><p>You can set a <code>belongsTo</code> foreign key. That is the full relation write model.</p><h2 id="auth-and-ui" tabindex="-1">Auth and UI <a class="header-anchor" href="#auth-and-ui" aria-label="Permalink to “Auth and UI”">​</a></h2><ul><li>No login page, session store, or password reset</li><li>No dashboards beyond model counts</li><li>No fieldsets, collapsed groups, or per-field help text</li><li>No plugin API</li></ul><h2 id="schema" tabindex="-1">Schema <a class="header-anchor" href="#schema" aria-label="Permalink to “Schema”">​</a></h2><ul><li>Composite primary keys (<code>@@id([a, b])</code>) — skipped</li><li>Models with no <code>@id</code> (views) — skipped</li><li><code>prisma.$queryRaw</code> / unmapped SQL — not introspected</li></ul><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to “Operations”">​</a></h2><ul><li>CSV / JSON export</li><li>Built-in audit table (you pass <code>audit.write</code>)</li><li>Row-level history tab</li></ul><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to “Deploy”">​</a></h2><ul><li>The Prisma schema file must ship with the app (or you pass <code>schemaPath</code>)</li><li>The UI is the pre-built bundle inside the package. You do not run a React build in the consumer app</li></ul><p>If you need something on this list, it is not a missing config key. It is not built.</p>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};